function generateColor(str) {
	// hash string → 0-360 hue
	let hash = 0;
	for (let i = 0; i < str.length; i++) {
		hash = str.charCodeAt(i) + ((hash << 5) - hash);
	}
	const hue = Math.abs(hash) % 360;

	// soft pastel color
	return `hsl(${hue}, 70%, 85%)`;
}

frappe.after_ajax(() => {
	renderServicePackets();
});

function renderServicePackets() {
	frappe.call({
		method: "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_tenant_subscribed_packets",
		args: {},
		callback: function (response) {
			const data = response.message;
			const container = root_element.querySelector("#service-packets");
			if (!container) return;

			container.innerHTML = "";

			Object.entries(data).forEach(([tenant, packets]) => {
				const tenantDiv = document.createElement("div");
				tenantDiv.className = "tenant-card";

				tenantDiv.innerHTML = `
					<div class="tenant-header">
						<div class="tenant-title">${tenant}</div>
						<div class="tenant-count">${packets.length} packets</div>
					</div>
					<div class="packet-grid"></div>
				`;

				const grid = tenantDiv.querySelector(".packet-grid");

				packets.forEach((p) => {
					const div = document.createElement("div");
					div.className = "packet-item";

					// dynamic color
					const color = generateColor(p.service_packet);
					div.style.setProperty("--clr", color);

					div.innerHTML = `
						<div class="packet-provider">${p.provider}</div>
						<div class="packet-service">${p.service_packet}</div>
					`;

					grid.appendChild(div);
				});

				container.appendChild(tenantDiv);
			});
		},
	});
}

style:
:root {
  --sp-border: #e5e7eb;
  --sp-muted: #6b7280;
  --sp-bg: #ffffff;
  --sp-shadow: 0 2px 6px rgba(0,0,0,0.06);
  --sp-shadow-hover: 0 8px 18px rgba(0,0,0,0.1);
}

/* Scroll container */
#service-packets.sp-scroll {
  max-height: 600px;
  overflow-y: auto;
  padding: 8px;
  border: 1px solid var(--sp-border);
  border-radius: 10px;
  background: var(--sp-bg);
  box-shadow: var(--sp-shadow);
}

/* Tenant block */
.tenant-card {
  background: #fff;
  border: 1px solid var(--sp-border);
  padding: 16px;
  margin-bottom: 18px;
  border-radius: 12px;
  box-shadow: var(--sp-shadow);
  transition: box-shadow .2s;
}
.tenant-card:hover {
  box-shadow: var(--sp-shadow-hover);
}

.tenant-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid #f1f5f9;
}

.tenant-title {
  font-size: 20px;
  font-weight: 700;
  color: #1f2937;
}

.tenant-count {
  font-size: 12px;
  padding: 3px 8px;
  background: #f3f4f6;
  border-radius: 999px;
}

/* Grid */
.packet-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 12px;
}

/* Packet card */
.packet-item {
  border-left: 8px solid var(--clr);   /* dynamic color */
  background: #fafafa;
  border: 1px solid var(--sp-border);
  padding: 14px;
  border-radius: 10px;
  transition: transform .15s, box-shadow .15s;
}
.packet-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--sp-shadow-hover);
}

/* Text */
.packet-provider {
  font-size: 12px;
  color: #6b7280;
  font-weight: 600;
}
.packet-service {
  font-size: 15px;
  font-weight: 700;
  margin-top: 5px;
  color: #111827;
}
